uint64_t OpenRuntime::revision()const{return impl->hookRevision.load();}
OpenRuntime::OpenRuntime():impl(std::make_unique<Impl>()){}OpenRuntime::~OpenRuntime()=default;
std::shared_ptr<OpenRuntime::Owner> OpenRuntime::owner(std::string id,const fs::path& package,const fs::path& data){auto p=std::make_shared<Owner>();p->host=impl.get();p->id=std::move(id);p->package=package;p->data=data;p->loader=GetCurrentThreadId();std::lock_guard l(impl->mutex);impl->owners.push_back(p);return p;}
