void OpenRuntime::layout(HWND host,float scale,float islandWidth,const std::vector<SceneNode>& nodes){RECT window{},client{};GetWindowRect(host,&window);GetClientRect(host,&client);window.left+=(LONG)std::lround((client.right-islandWidth*scale)/2);std::lock_guard lock(impl->mutex);for(auto& [id,v]:impl->views){std::lock_guard l(v->mutex);auto n=std::find_if(nodes.begin(),nodes.end(),[&](auto& node){return node.id==v->def.element&&node.owner==v->owner->id;});v->visible=n!=nodes.end()&&IsWindowVisible(host);if(n!=nodes.end()){auto info=n->info();v->desired={window.left+(LONG)std::lround(info.x*scale),window.top+(LONG)std::lround(info.y*scale),window.left+(LONG)std::lround((info.x+info.width)*scale),window.top+(LONG)std::lround((info.y+info.height)*scale)};v->dpi=(uint32_t)std::lround(96*scale);v->radius=(float)n->n(WI_RADIUS);v->opacity=(float)n->n(WI_OPACITY,0,1);}}}
WiHostPacket OpenRuntime::route(WiHostPacket packet){if(!Impl::valid(packet))return {};std::vector<Impl::Hook> list;{std::lock_guard l(impl->mutex);list=impl->hooks;}std::stable_sort(list.begin(),list.end(),[](auto& a,auto& b){return a.def.priority!=b.def.priority?a.def.priority>b.def.priority:a.owner->id<b.owner->id;});for(auto& h:list)if(!h.owner->stopping&&h.def.topic==packet.topic){bool live;{std::lock_guard l(impl->mutex);live=std::any_of(impl->hooks.begin(),impl->hooks.end(),[&](auto& p){return p.id==h.id;});}if(!live)continue;auto changed=packet;int rc=safeHook(h.def.callback,h.def.context,&changed);if(rc<0){writeAtomic(h.owner->data/L"hook-error.txt","Hook callback failed, id="+std::to_string(h.id)+" code="+std::to_string(rc));continue;}if(rc==WI_HOOK_CONSUME){packet.flags|=0x80000000u;break;}if(rc==WI_HOOK_REPLACE&&Impl::valid(changed)&&changed.topic==packet.topic){changed.sequence=packet.sequence;strcpy_s(changed.source,packet.source);packet=changed;}}return packet;}
bool OpenRuntime::enqueue(WiHostPacket packet){if(!Impl::valid(packet))return false;std::lock_guard l(impl->mutex);if(impl->queue.size()>=256)return false;impl->queue.push_back(packet);return true;}
void OpenRuntime::pump(){std::vector<std::shared_ptr<Impl::Process>> processes;std::deque<WiHostPacket> q;{std::lock_guard l(impl->mutex);for(auto& [id,p]:impl->processes)processes.push_back(p);q.swap(impl->queue);}for(auto& p:processes)p->poll();for(auto& p:q){auto result=route(p);std::lock_guard l(impl->mutex);if(impl->results.size()>=256)impl->results.pop_front();impl->results.push_back(result);}}
